INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Site-to-Site-VPN dasselbe wie ein End-to-End-VPN?', 2, '[{"text": "Nein", "correct": true, "because": "Standorte vs. Geräte"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat ein Site-to-Site-VPN?', 3, '[{"text": "Verbindung zwischen Netzwerken", "correct": true, "because": "Standorte verbinden"}, {"text": "Einzelgeräte absichern", "correct": false, "because": "Remote Access VPN"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Teilfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für ein Site-to-Site-VPN wichtig?', 5, '[{"text": "VPN-Gateways", "correct": true, "because": "Verbindungspunkte"}, {"text": "Tunnels", "correct": true, "because": "Sichere Datenübertragung"}, {"text": "USB-Sticks", "correct": false, "because": "Kein VPN-Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Site-to-Site-VPN verbindet Netzwerke. b) Es wird nur für Einzelnutzer verwendet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht für Einzelnutzer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Site-to-Site-VPN?', 4, '[{"text": "Verschlüsselung", "correct": false, "because": "Sicherheit zentral"}, {"text": "Gateway-Konfiguration", "correct": false, "because": "Verbindung nötig"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Site-to-Site-VPN eine Internetverbindung benötigt?', 2, '[{"text": "Ja", "correct": true, "because": "Über Internet"}, {"text": "Nein", "correct": false, "because": "Internet nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird oft für Site-to-Site-VPNs genutzt?', 3, '[{"text": "IPSec", "correct": true, "because": "Sichere Verbindung"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}, {"text": "FTP", "correct": false, "because": "Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Site-to-Site-VPN?', 5, '[{"text": "Sichere Netzwerkverbindung", "correct": true, "because": "Verschlüsselung"}, {"text": "Transparenz für Nutzer", "correct": true, "because": "Keine Client-Software"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Site-to-Site-VPN verbindet Standorte. b) Es ist für Einzelgeräte gedacht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht für Einzelgeräte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Site-to-Site-VPN?', 4, '[{"text": "VPN-Gateway", "correct": false, "because": "Verbindungspunkt"}, {"text": "Verschlüsselung", "correct": false, "because": "Sicherheit"}, {"text": "Physische Kabel", "correct": true, "because": "Über Internet"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Site-to-Site-VPN dasselbe wie ein Remote Access VPN?', 2, '[{"text": "Nein", "correct": true, "because": "Netzwerke vs. Nutzer"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte sind für ein Site-to-Site-VPN typisch?', 4, '[{"text": "Router", "correct": true, "because": "Gateway-Funktion"}, {"text": "Firewalls", "correct": true, "because": "Sicherheit"}, {"text": "USB-Drucker", "correct": false, "because": "Kein VPN-Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Site-to-Site-VPN keine Verschlüsselung braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit zentral"}, {"text": "Ja", "correct": false, "because": "Verschlüsselung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Site-to-Site-VPN?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Daten schützen"}, {"text": "Kabellänge", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Sicherheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Site-to-Site-VPN nutzt IPSec. b) Es ist nur für kleine Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Größe flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen Site-to-Site-VPNs?', 5, '[{"text": "IPSec", "correct": true, "because": "Verschlüsselung"}, {"text": "MPLS", "correct": true, "because": "Alternative"}, {"text": "Bluetooth", "correct": false, "because": "Kein VPN-Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Site-to-Site-VPN unwichtig?', 3, '[{"text": "Verschlüsselung", "correct": false, "because": "Sicherheit"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Grundlage"}, {"text": "Papierdokumente", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Site-to-Site-VPN über das Internet laufen?', 3, '[{"text": "Ja", "correct": true, "because": "Öffentliches Netz"}, {"text": "Nein", "correct": false, "because": "Internet üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Site-to-Site-VPN für Remote-Arbeiter ist?', 2, '[{"text": "Nein", "correct": true, "because": "Standorte verbinden"}, {"text": "Ja", "correct": false, "because": "Remote Access anders"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für ein Site-to-Site-VPN zentral?', 4, '[{"text": "Sichere Netzwerkverbindung", "correct": true, "because": "Kernprinzip"}, {"text": "Einzelgerätezugriff", "correct": false, "because": "Nicht Ziel"}, {"text": "Physische Kabel", "correct": false, "because": "Internetbasiert"}]');
